         (x1 gp tp x6 x7 x8 x9 x10 x12 x13 x14 x16 x17 x19 x20 x22 x23 x24 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH S2 L2 pt PTR BITS PP PE : Z) (w224 : word),
    PTR = S2 + pt ->
    w4s_src_ctx RNG mm SS n SBL SBH ->
    n < 2^26 ->
    SS <= S2 ->
    S2 + L2 <= SS + n ->
    rw_cells asegs mm (P + 184) [C8 (Z_to_bv 64 (S2 + 8))] ->
    rw_cells asegs mm (P + 224) [C8 w224] ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    KXGoM.apart SS n P 496 ->
    8 <= pt ->
    pt + 8 <= L2 ->
    0 <= BITS <= 64 ->
    0x60d000 <= PP ->
    PP < PE + -3 ->
    PE <= 2^47 ->
    (forall (mm' : amem) (PT' : Z) (bw cw : word) (y6 y8 y13 y14 y29 y30 : word),
       munch [(P + 224, P + 232)] mm mm' ->
       wmono asegs mm mm' ->
       mem_inv asegs mm' ->
       rw_cells asegs mm' (P + 224) [C8 cw] ->
       PTR - 8 <= PT' <= PTR ->
       0 <= bv_unsigned bw <= 7 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) y6 x7 y8 x9 x10 (Z_to_bv 64 PP) x12 y13 y14
           (Z_to_bv 64 PP) x16 x17 (Z_to_bv 64 S2) x19 x20 bw x22 x23 x24 (Z_to_bv 64 PT') x26 x27 x28 y29 y30 cw) F
           (Z_to_bv 64 0x91f5c) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) x6 x7 x8 x9 x10 (Z_to_bv 64 PP) x12 x13 x14
        (Z_to_bv 64 PP) x16 x17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 BITS) x22 x23 x24 (Z_to_bv 64 PTR) x26 x27 x28 x29
        x30 x31) F (Z_to_bv 64 0x91e84) fc None mm (seg_rom asegs)).

