(* [comment removed for export] *)
Definition w4s32_Rfg_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x6 x7 x8 x9 x10 x12 x13 x14 x16 x17 x19 x20 x22 x23 x24 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH S2 L2 pt PTR BITS PP PE DESC S3 : Z),
    PTR = S2 + pt ->
    w4s_src_ctx RNG mm SS n SBL SBH ->
    n < 2^26 ->
    SS <= S2 ->
    S2 + L2 <= SS + n ->
    rw_cells asegs mm (P + 184) [C8 (Z_to_bv 64 (S2 + 8))] ->
    rw_cells asegs mm (P + 104) [C8 (Z_to_bv 64 DESC)] ->
    rw_cells asegs mm (P + 112) [C8 (Z_to_bv 64 S3)] ->
    rw_cells asegs mm (P + 200) [C8 (Z_to_bv 64 PE)] ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    KXGoM.apart SS n P 496 ->
    8 <= pt ->
    pt + 8 <= L2 ->
    0 <= BITS <= 64 ->
    0x60d000 <= PP ->
    PE + -3 <= PP ->
    PP < 2^47 ->
    0x60d000 <= PE + -3 ->
    PE <= 2^47 ->
    0 <= DESC < 2^64 ->
    0 <= S3 < 2^64 ->
    (forall (PT' : Z) (bw cw : word) (y6 y13 y14 y25 y30 : word),
       PTR - 8 <= PT' <= PTR ->
       0 <= bv_unsigned bw <= 7 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) y6 x7 (Z_to_bv 64 S3) x9 x10 (Z_to_bv 64 PP)
           (Z_to_bv 64 PT') y13 y14 (Z_to_bv 64 PP) x16 x17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 DESC) x22 x23 x24 y25
           x26 x27 bw (Z_to_bv 64 PE) y30 cw) F (Z_to_bv 64 0x9232c) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) x6 x7 x8 x9 x10 (Z_to_bv 64 PP) x12 x13 x14
        (Z_to_bv 64 PP) x16 x17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 BITS) x22 x23 x24 (Z_to_bv 64 PTR) x26 x27 x28 x29
        x30 x31) F (Z_to_bv 64 0x91e84) fc None mm (seg_rom asegs)).

